1	import Phaser from 'phaser';
2	import { KEYS } from '../config/assetManifest';
3	import { DEPTH, HUD, GAME_WIDTH, MAX_HP } from '../config/gameConfig';
4	import { t } from '../i18n/strings';
5	import { GameEvents, type ArmorState } from '../scenes/gameEvents';
6	import { AudioManager } from '../systems/AudioManager';
7	import { playSfx, Sfx } from '../systems/audio';
8	
9	export interface HudOptions {
10	  /** Invoked when the pause button is tapped. */
11	  onPause: () => void;
12	}
13	
14	export interface HudSnapshot {
15	  hp: number;
16	  score: number;
17	  progress: number;
18	}
19	
20	/**
21	 * Hud — the persistent in-run overlay (spec §6.2). It is purely a VIEW: it never
22	 * reaches into the run loop, only SUBSCRIBES to the events GameScene emits on
23	 * `scene.events` and re-paints. Hearts (shape+fill), score, a level-progress bar
24	 * (dynamic fill drawn through the frame's transparent window), plus pause + mute
25	 * controls and a small armor tell. Resets on `run:start`, freezes on `run:end`,
26	 * and removes every listener on scene shutdown (no leaks across replays).
27	 */
28	export class Hud {
29	  private readonly scene: Phaser.Scene;
30	  private readonly opts: HudOptions;
31	
32	  private readonly hearts: Phaser.GameObjects.Image[] = [];
33	  private readonly scoreText: Phaser.GameObjects.Text;
34	  private readonly progressFill: Phaser.GameObjects.Rectangle;
35	  private readonly pauseBtn: Phaser.GameObjects.Image;
36	  private readonly muteBtn: Phaser.GameObjects.Image;
37	  private readonly armorIcon: Phaser.GameObjects.Image;
38	
39	  private armorTween: Phaser.Tweens.Tween | undefined;
40	  private readonly progressUsableWidth: number;
41	  private frozen = false;
42	
43	  constructor(scene: Phaser.Scene, opts: HudOptions, initial?: HudSnapshot) {
44	    this.scene = scene;
45	    this.opts = opts;
46	    this.progressUsableWidth = HUD.progressBarWidth - HUD.progressFillInsetX * 2;
47	
48	    // ── Progress bar: frame asset + a dynamic fill drawn on top ──
49	    scene.add.image(GAME_WIDTH / 2, HUD.progressBarY, KEYS.ui_progress_bar).setDepth(DEPTH.hud);
50	    const fillLeft = GAME_WIDTH / 2 - this.progressUsableWidth / 2;
51	    this.progressFill = scene.add
52	      .rectangle(fillLeft, HUD.progressBarY, this.progressUsableWidth, HUD.progressFillHeight, HUD.progressFillColor)
53	      .setOrigin(0, 0.5)
54	      .setDepth(DEPTH.hud);
55	    this.progressFill.scaleX = 0;
56	
57	    // ── Score row ──
58	    scene.add.image(HUD.scoreIconX, HUD.scoreRowY, KEYS.ui_score_icon).setDepth(DEPTH.hud);
59	    this.scoreText = scene.add
60	      .text(HUD.scoreTextX, HUD.scoreRowY, this.scoreLabel(0), {
61	        fontFamily: 'system-ui, sans-serif',
62	        fontSize: HUD.scoreFontSize,
63	        fontStyle: 'bold',
64	        color: HUD.scoreColor,
65	        stroke: HUD.scoreStrokeColor,
66	        strokeThickness: HUD.scoreStrokeThickness,
67	      })
68	      .setOrigin(0, 0.5)
69	      .setDepth(DEPTH.hud);
70	
71	    // ── Hearts ──
72	    for (let i = 0; i < MAX_HP; i++) {
73	      this.hearts.push(
74	        scene.add.image(HUD.heartStartX + i * HUD.heartSpacing, HUD.heartY, KEYS.ui_heart_full).setDepth(DEPTH.hud),
75	      );
76	    }
77	
78	    // ── Small armor tell (hidden until armored) ──
79	    this.armorIcon = scene.add
80	      .image(HUD.armorTellX, HUD.armorTellY, KEYS.armor_pickup)
81	      .setScale(HUD.armorTellScale)
82	      .setDepth(DEPTH.hud)
83	      .setVisible(false);
84	
85	    // ── Controls (mute then pause, top-right) ──
86	    this.muteBtn = scene.add
87	      .image(HUD.muteBtnX, HUD.muteBtnY, this.muteTexture())
88	      .setDepth(DEPTH.hud)
89	      .setInteractive({ useHandCursor: true });
90	    this.muteBtn.on(Phaser.Input.Events.POINTER_UP, this.onMuteTap, this);
91	
92	    this.pauseBtn = scene.add
93	      .image(HUD.pauseBtnX, HUD.pauseBtnY, KEYS.ui_btn_pause)
94	      .setDepth(DEPTH.hud)
95	      .setInteractive({ useHandCursor: true });
96	    this.pauseBtn.on(Phaser.Input.Events.POINTER_UP, this.onPauseTap, this);
97	
98	    if (initial) {
99	      this.setHp(initial.hp);
100	      this.setScore(initial.score);
101	      this.setProgress(initial.progress);
102	    }
103	
104	    // ── Subscriptions ──
105	    const ev = scene.events;
106	    ev.on(GameEvents.hp, this.onHp, this);
107	    ev.on(GameEvents.score, this.onScore, this);
108	    ev.on(GameEvents.progress, this.onProgress, this);
109	    ev.on(GameEvents.armor, this.onArmor, this);
110	    ev.on(GameEvents.runStart, this.onRunStart, this);
111	    ev.on(GameEvents.runEnd, this.onRunEnd, this);
112	    ev.once(Phaser.Scenes.Events.SHUTDOWN, this.destroy, this);
113	  }
114	
115	  /** Re-read the shared mute state and repaint the icon (e.g. after resume). */
116	  syncMute(): void {
117	    this.muteBtn.setTexture(this.muteTexture());
118	  }
119	
120	  destroy(): void {
121	    const ev = this.scene.events;
122	    ev.off(GameEvents.hp, this.onHp, this);
123	    ev.off(GameEvents.score, this.onScore, this);
124	    ev.off(GameEvents.progress, this.onProgress, this);
125	    ev.off(GameEvents.armor, this.onArmor, this);
126	    ev.off(GameEvents.runStart, this.onRunStart, this);
127	    ev.off(GameEvents.runEnd, this.onRunEnd, this);
128	    ev.off(Phaser.Scenes.Events.SHUTDOWN, this.destroy, this);
129	    this.stopArmorTell();
130	    // Display objects are scene-owned and auto-destroyed on shutdown.
131	  }
132	
133	  // ── Event handlers ──────────────────────────────────────────────────────────
134	  private onHp(hp: number): void {
135	    if (this.frozen) return;
136	    this.setHp(hp);
137	  }
138	
139	  private onScore(score: number): void {
140	    if (this.frozen) return;
141	    this.setScore(score);
142	  }
143	
144	  private onProgress(progress: number): void {
145	    if (this.frozen) return;
146	    this.setProgress(progress);
147	  }
148	
149	  private onArmor(state: ArmorState): void {
150	    if (this.frozen) return;
151	    if (state.active) this.startArmorTell();
152	    else this.stopArmorTell();
153	  }
154	
155	  private onRunStart(): void {
156	    this.frozen = false;
157	    this.setHp(MAX_HP);
158	    this.setScore(0);
159	    this.setProgress(0);
160	    this.stopArmorTell();
161	    this.pauseBtn.setAlpha(1).setInteractive({ useHandCursor: true });
162	  }
163	
164	  private onRunEnd(): void {
165	    // Freeze the HUD in its final state; pausing is meaningless once the run ends.
166	    this.frozen = true;
167	    this.stopArmorTell();
168	    this.pauseBtn.disableInteractive();
169	    this.pauseBtn.setAlpha(HUD.frozenBtnAlpha);
170	  }
171	
172	  // ── Control taps ─────────────────────────────────────────────────────────────
173	  private onMuteTap(): void {
174	    AudioManager.toggle(this.scene.sound);
175	    this.syncMute();
176	    playSfx(this.scene, Sfx.ui);
177	  }
178	
179	  private onPauseTap(): void {
180	    if (this.frozen) return;
181	    playSfx(this.scene, Sfx.ui);
182	    this.opts.onPause();
183	  }
184	
185	  // ── Painters ─────────────────────────────────────────────────────────────────
186	  private setHp(hp: number): void {
187	    this.hearts.forEach((img, i) => {
188	      img.setTexture(i < hp ? KEYS.ui_heart_full : KEYS.ui_heart_empty);
189	    });
190	  }
191	
192	  private setScore(score: number): void {
193	    this.scoreText.setText(this.scoreLabel(score));
194	  }
195	
196	  private setProgress(progress: number): void {
197	    this.progressFill.scaleX = Phaser.Math.Clamp(progress, 0, 1);
198	  }
199	
200	  private scoreLabel(score: number): string {
201	    return `${t('hud_score')}: ${score}`;
202	  }
203	
204	  private muteTexture(): string {
205	    return AudioManager.isMuted() ? KEYS.ui_btn_mute_off : KEYS.ui_btn_mute_on;
206	  }
207	
208	  private startArmorTell(): void {
209	    this.armorIcon.setVisible(true).setScale(HUD.armorTellScale);
210	    if (this.armorTween) return;
211	    this.armorTween = this.scene.tweens.add({
212	      targets: this.armorIcon,
213	      scale: { from: HUD.armorTellScale, to: HUD.armorTellPulseScale },
214	      duration: HUD.armorTellPulseMs,
215	      yoyo: true,
216	      repeat: -1,
217	      ease: 'Sine.inOut',
218	    });
219	  }
220	
221	  private stopArmorTell(): void {
222	    this.armorTween?.stop();
223	    this.armorTween = undefined;
224	    this.armorIcon.setVisible(false).setScale(HUD.armorTellScale);
225	  }
226	}
