11	/**
12	 * ResultsScene — Victory or Game Over depending on the `result` param, the final
13	 * score, the promo-code chip, the buy CTA (fires `click_buy` then opens the
14	 * UTM-tagged buy URL in a new tab), and Play-again (→ a fresh run).
15	 */
16	export class ResultsScene extends Phaser.Scene {
17	  constructor() {
18	    super({ key: SceneKey.Results });
19	  }
20	
21	  create(data: Partial<FinishGameParams> = {}): void {
22	    // Robust if entered without/with partial data (e.g. deep-link, hot reload):
23	    // default to a Game-Over result and a zero score.
24	    const win = data.result === 'win';
25	    const score = typeof data.score === 'number' ? data.score : 0;
26	    const cx = GAME_WIDTH / 2;
