37	        fontFamily: 'system-ui, sans-serif',
38	        fontSize: '48px',
39	        fontStyle: 'bold',
40	        color: '#20272e',
41	      })
42	      .setOrigin(0.5);
43	
44	    this.add
45	      .text(cx, 380, t('results_score', { score }), {
46	        fontFamily: 'system-ui, sans-serif',
47	        fontSize: '30px',
48	        color: '#20272e',
49	      })
50	      .setOrigin(0.5);
51	
52	    // Promo chip + code.
53	    this.add.image(cx, 460, KEYS.ui_promo_chip);
54	    this.add
55	      .text(cx, 460, `${t('results_promo_label')} ${ENV.promoCode}`, {
56	        fontFamily: 'monospace',
57	        fontSize: '26px',
58	        fontStyle: 'bold',
59	        color: '#20272e',
60	      })
61	      .setOrigin(0.5);
62	
63	    // The conversion CTA.
64	    createButton(this, {
65	      x: cx,
66	      y: 565,
67	      texture: KEYS.ui_btn_cta,
68	      label: t('results_cta'),
69	      onClick: () => this.onBuy(),
70	    });
71	
72	    // Secondary: play again → fresh run (a new start_game fires in GameScene).
73	    createButton(this, {
74	      x: cx,
75	      y: 660,
