1	import Phaser from 'phaser';
2	import { AUDIO } from '../config/gameConfig';
3	
4	/**
5	 * audio.ts — placeholder SFX + music, 100% static-hostable with NO external
6	 * files or network. Sounds are SYNTHESIZED at runtime (simple Web Audio-style
7	 * oscillator maths) into 16-bit PCM WAV blobs, then handed to Phaser's normal
8	 * loader (`load.audio`). Playback goes through the scene's shared sound manager,
9	 * so the persisted mute + iOS unlock owned by AudioManager apply automatically —
10	 * this module never touches mute state itself.
11	 *
12	 * Phase 5 can drop in real assets by replacing `registerAudio()` with real
13	 * `loader.audio(key, ['x.m4a','x.ogg'])` calls under the same keys; nothing else
14	 * needs to change.
15	 */
16	
17	// ── Sound keys ───────────────────────────────────────────────────────────────
18	export const Sfx = {
19	  jump: 'sfx_jump',
20	  hit: 'sfx_hit',
21	  tablet: 'sfx_tablet',
22	  armor: 'sfx_armor',
23	  victory: 'sfx_victory',
24	  defeat: 'sfx_defeat',
25	  ui: 'sfx_ui',
26	} as const;
27	export type SfxKey = (typeof Sfx)[keyof typeof Sfx];
28	
29	export const Music = {
30	  menu: 'music_menu',
31	  game: 'music_game',
32	} as const;
33	export type MusicKey = (typeof Music)[keyof typeof Music];
34	
35	// ── Note frequencies (Hz) used by the little placeholder tunes/stings ─────────
36	const C3 = 130.81;
37	const F3 = 174.61;
38	const G3 = 196.0;
39	const A3 = 220.0;
40	const C4 = 261.63;
41	const D4 = 293.66;
42	const E4 = 329.63;
43	const F4 = 349.23;
44	const G4 = 392.0;
45	const A4 = 440.0;
46	const B4 = 493.88;
47	const C5 = 523.25;
48	const E5 = 659.25;
49	const G5 = 783.99;
50	const B5 = 987.77;
51	const C6 = 1046.5;
52	
53	const SFX_SR = 44100; // short, crisp
54	const MUSIC_SR = 22050; // longer loops — half rate keeps the blobs small
55	
56	// ── Oscillators ──────────────────────────────────────────────────────────────
57	type WaveType = 'sine' | 'square' | 'triangle' | 'saw' | 'noise';
58	
59	function waveSample(type: WaveType, phase: number): number {
60	  const p = phase - Math.floor(phase); // wrap to [0,1)
61	  switch (type) {
62	    case 'sine':
63	      return Math.sin(p * Math.PI * 2);
64	    case 'square':
65	      return p < 0.5 ? 1 : -1;
66	    case 'triangle':
67	      return 4 * Math.abs(p - 0.5) - 1;
68	    case 'saw':
69	      return 2 * p - 1;
70	    case 'noise':
71	      return Math.random() * 2 - 1;
72	    default:
73	      return 0;
74	  }
75	}
76	
77	/** A percussive tone: fast attack, power-curve decay, optional pitch glide. */
78	interface ToneOpts {
79	  start: number;
80	  dur: number;
81	  freq: number;
82	  freqEnd?: number;
83	  type?: WaveType;
84	  gain?: number;
85	  attack?: number;
86	  decayPow?: number;
87	}
88	
89	function addTone(buf: Float32Array, sr: number, o: ToneOpts): void {
90	  const type = o.type ?? 'sine';
91	  const gain = o.gain ?? 0.3;
92	  const attack = o.attack ?? 0.005;
93	  const decayPow = o.decayPow ?? 2;
94	  const freqEnd = o.freqEnd ?? o.freq;
95	  const n0 = Math.max(0, Math.floor(o.start * sr));
96	  const n1 = Math.min(buf.length, Math.floor((o.start + o.dur) * sr));
97	  let phase = 0;
98	  for (let i = n0; i < n1; i++) {
99	    const t = (i - n0) / sr;
100	    const u = t / o.dur;
101	    const f = o.freq + (freqEnd - o.freq) * u;
102	    phase += f / sr;
103	    const a = attack > 0 ? Math.min(t / attack, 1) : 1;
104	    const env = a * Math.pow(1 - u, decayPow);
105	    buf[i] = (buf[i] ?? 0) + gain * env * waveSample(type, phase);
106	  }
107	}
108	
109	/** A sustained pad: attack/release ramps with an optional gentle vibrato. */
110	interface PadOpts {
111	  start: number;
112	  dur: number;
113	  freq: number;
114	  type?: WaveType;
115	  gain?: number;
116	  attack?: number;
117	  release?: number;
118	  vibratoHz?: number;
119	  vibratoDepth?: number;
120	}
121	
122	function addPad(buf: Float32Array, sr: number, o: PadOpts): void {
123	  const type = o.type ?? 'sine';
124	  const gain = o.gain ?? 0.2;
125	  const attack = o.attack ?? 0.02;
126	  const release = o.release ?? 0.08;
127	  const vibratoHz = o.vibratoHz ?? 0;
128	  const vibratoDepth = o.vibratoDepth ?? 0;
129	  const n0 = Math.max(0, Math.floor(o.start * sr));
130	  const n1 = Math.min(buf.length, Math.floor((o.start + o.dur) * sr));
131	  let phase = 0;
132	  for (let i = n0; i < n1; i++) {
133	    const t = (i - n0) / sr;
134	    const rem = o.dur - t;
135	    const a = attack > 0 ? Math.min(t / attack, 1) : 1;
136	    const r = release > 0 ? Math.min(rem / release, 1) : 1;
137	    const env = Math.max(0, Math.min(a, r));
138	    const vib = vibratoHz > 0 ? 1 + vibratoDepth * Math.sin(t * vibratoHz * Math.PI * 2) : 1;
139	    phase += (o.freq * vib) / sr;
140	    buf[i] = (buf[i] ?? 0) + gain * env * waveSample(type, phase);
141	  }
142	}
143	
144	// ── Sound recipes ────────────────────────────────────────────────────────────
145	function makeJump(): Float32Array {
146	  const sr = SFX_SR;
147	  const buf = new Float32Array(Math.floor(sr * 0.18));
148	  addTone(buf, sr, { start: 0, dur: 0.16, freq: 470, freqEnd: 900, type: 'square', gain: 0.32, decayPow: 2.4 });
149	  addTone(buf, sr, { start: 0, dur: 0.16, freq: 470, freqEnd: 900, type: 'sine', gain: 0.18 });
150	  return buf;
151	}
152	
153	function makeHit(): Float32Array {
154	  const sr = SFX_SR;
155	  const buf = new Float32Array(Math.floor(sr * 0.22));
156	  addTone(buf, sr, { start: 0, dur: 0.1, freq: 1, type: 'noise', gain: 0.35, decayPow: 3 });
157	  addTone(buf, sr, { start: 0, dur: 0.18, freq: 240, freqEnd: 80, type: 'square', gain: 0.3, decayPow: 2 });
158	  return buf;
159	}
160	
161	function makeTablet(): Float32Array {
162	  const sr = SFX_SR;
163	  const buf = new Float32Array(Math.floor(sr * 0.2));
164	  addTone(buf, sr, { start: 0, dur: 0.18, freq: 880, type: 'sine', gain: 0.28, decayPow: 2.4 });
165	  addTone(buf, sr, { start: 0.0, dur: 0.16, freq: 1320, type: 'sine', gain: 0.16, decayPow: 2.6 });
166	  addTone(buf, sr, { start: 0.02, dur: 0.14, freq: 1760, type: 'sine', gain: 0.1, decayPow: 3 });
167	  return buf;
168	}
169	
170	function makeArmor(): Float32Array {
171	  const sr = SFX_SR;
172	  const buf = new Float32Array(Math.floor(sr * 0.4));
173	  addTone(buf, sr, { start: 0.0, dur: 0.16, freq: E5, type: 'triangle', gain: 0.22, decayPow: 2 });
174	  addTone(buf, sr, { start: 0.09, dur: 0.16, freq: G5, type: 'triangle', gain: 0.22, decayPow: 2 });
175	  addTone(buf, sr, { start: 0.18, dur: 0.2, freq: B5, type: 'triangle', gain: 0.24, decayPow: 1.8 });
176	  addTone(buf, sr, { start: 0.0, dur: 0.36, freq: 300, freqEnd: 1200, type: 'sine', gain: 0.12, decayPow: 1.4 });
177	  return buf;
178	}
179	
180	function makeVictory(): Float32Array {
181	  const sr = SFX_SR;
182	  const buf = new Float32Array(Math.floor(sr * 0.7));
183	  const seq: Array<[number, number]> = [
184	    [0.0, C5],
185	    [0.12, E5],
186	    [0.24, G5],
187	    [0.36, C6],
188	  ];
189	  for (const [s, f] of seq) {
190	    addTone(buf, sr, { start: s, dur: 0.3, freq: f, type: 'triangle', gain: 0.24, decayPow: 1.6 });
191	  }
192	  addTone(buf, sr, { start: 0.36, dur: 0.32, freq: G5, type: 'sine', gain: 0.12, decayPow: 1.4 });
193	  return buf;
194	}
195	
196	function makeDefeat(): Float32Array {
197	  const sr = SFX_SR;
198	  const buf = new Float32Array(Math.floor(sr * 0.7));
199	  const seq: Array<[number, number]> = [
200	    [0.0, G4],
201	    [0.16, E4],
202	    [0.32, C4],
203	    [0.48, G3],
204	  ];
205	  for (const [s, f] of seq) {
206	    addTone(buf, sr, { start: s, dur: 0.34, freq: f, type: 'triangle', gain: 0.24, decayPow: 1.5 });
207	  }
208	  return buf;
209	}
210	
211	function makeUi(): Float32Array {
212	  const sr = SFX_SR;
213	  const buf = new Float32Array(Math.floor(sr * 0.07));
214	  addTone(buf, sr, { start: 0, dur: 0.06, freq: 660, freqEnd: 760, type: 'sine', gain: 0.28, decayPow: 3 });
215	  return buf;
216	}
217	
218	function makeMenuMusic(): Float32Array {
219	  const sr = MUSIC_SR;
220	  const step = 0.9;
221	  const loop = step * 4;
222	  const buf = new Float32Array(Math.floor(sr * loop));
223	  // Calm I–V–vi–IV pad progression (C, G, Am, F).
224	  const chords: Array<[number, number, number]> = [
225	    [C4, E4, G4],
226	    [G3, B4, D4],
227	    [A3, C5, E4],
228	    [F3, A4, C5],
229	  ];
230	  chords.forEach((c, i) => {
231	    const start = i * step;
232	    addPad(buf, sr, { start, dur: step * 0.98, freq: c[0], type: 'triangle', gain: 0.13, attack: 0.06, release: 0.22, vibratoHz: 5, vibratoDepth: 0.004 });
233	    addPad(buf, sr, { start, dur: step * 0.98, freq: c[1], type: 'sine', gain: 0.09, attack: 0.08, release: 0.22 });
234	    addPad(buf, sr, { start, dur: step * 0.98, freq: c[2], type: 'sine', gain: 0.09, attack: 0.08, release: 0.22 });
235	  });
236	  // Light melody over the top.
237	  const mel: Array<[number, number]> = [
238	    [0.0, G4],
239	    [0.9, C5],
240	    [1.8, A4],
241	    [2.7, G4],
242	  ];
243	  for (const [s, f] of mel) {
244	    addTone(buf, sr, { start: s, dur: 0.5, freq: f, type: 'sine', gain: 0.11, attack: 0.02, decayPow: 1.2 });
245	  }
246	  return buf;
247	}
248	
249	function makeGameMusic(): Float32Array {
250	  const sr = MUSIC_SR;
251	  const loop = 3.2;
252	  const buf = new Float32Array(Math.floor(sr * loop));
253	  // Driving bass pulse.
254	  const bass = [C3, C3, G3, G3, A3, A3, F3, F3];
255	  bass.forEach((f, i) => {
256	    addTone(buf, sr, { start: i * 0.4, dur: 0.36, freq: f, type: 'square', gain: 0.12, decayPow: 1.6 });
257	  });
258	  // Upbeat arpeggio lead.
259	  const arp = [C4, E4, G4, C5, G4, E4, A4, C5, E4, A4, C5, E4, F4, A4, C5, F4];
260	  arp.forEach((f, i) => {
261	    addTone(buf, sr, { start: i * 0.2, dur: 0.18, freq: f, type: 'triangle', gain: 0.11, decayPow: 2 });
262	  });
263	  return buf;
264	}
265	
266	// ── WAV encoding + blob URLs ─────────────────────────────────────────────────
267	function encodeWav(samples: Float32Array, sampleRate: number): ArrayBuffer {
268	  const buffer = new ArrayBuffer(44 + samples.length * 2);
269	  const view = new DataView(buffer);
270	  const writeStr = (offset: number, s: string): void => {
271	    for (let i = 0; i < s.length; i++) view.setUint8(offset + i, s.charCodeAt(i));
272	  };
273	  writeStr(0, 'RIFF');
274	  view.setUint32(4, 36 + samples.length * 2, true);
275	  writeStr(8, 'WAVE');
276	  writeStr(12, 'fmt ');
277	  view.setUint32(16, 16, true); // PCM header size
278	  view.setUint16(20, 1, true); // format = PCM
279	  view.setUint16(22, 1, true); // mono
280	  view.setUint32(24, sampleRate, true);
281	  view.setUint32(28, sampleRate * 2, true); // byte rate
282	  view.setUint16(32, 2, true); // block align
283	  view.setUint16(34, 16, true); // bits per sample
284	  writeStr(36, 'data');
285	  view.setUint32(40, samples.length * 2, true);
286	  let offset = 44;
287	  for (let i = 0; i < samples.length; i++) {
288	    const s = Math.max(-1, Math.min(1, samples[i] ?? 0));
289	    view.setInt16(offset, s < 0 ? s * 0x8000 : s * 0x7fff, true);
290	    offset += 2;
291	  }
292	  return buffer;
293	}
294	
295	function wavUrl(samples: Float32Array, sampleRate: number): string {
296	  const blob = new Blob([encodeWav(samples, sampleRate)], { type: 'audio/wav' });
297	  return URL.createObjectURL(blob);
298	}
299	
300	interface AudioDef {
301	  readonly key: string;
302	  readonly sr: number;
303	  readonly make: () => Float32Array;
304	}
305	
306	const AUDIO_DEFS: readonly AudioDef[] = [
307	  { key: Sfx.jump, sr: SFX_SR, make: makeJump },
308	  { key: Sfx.hit, sr: SFX_SR, make: makeHit },
309	  { key: Sfx.tablet, sr: SFX_SR, make: makeTablet },
310	  { key: Sfx.armor, sr: SFX_SR, make: makeArmor },
311	  { key: Sfx.victory, sr: SFX_SR, make: makeVictory },
312	  { key: Sfx.defeat, sr: SFX_SR, make: makeDefeat },
313	  { key: Sfx.ui, sr: SFX_SR, make: makeUi },
314	  { key: Music.menu, sr: MUSIC_SR, make: makeMenuMusic },
315	  { key: Music.game, sr: MUSIC_SR, make: makeGameMusic },
316	];
317	
318	// Generate the blob URLs once (idempotent across scene reloads).
319	let urlCache: Map<string, string> | undefined;
320	function audioUrls(): Map<string, string> {
321	  if (!urlCache) {
322	    urlCache = new Map();
323	    for (const def of AUDIO_DEFS) urlCache.set(def.key, wavUrl(def.make(), def.sr));
324	  }
325	  return urlCache;
326	}
327	
328	/** Queue every placeholder sound onto the scene's loader (call from PreloadScene). */
329	export function registerAudio(scene: Phaser.Scene): void {
330	  const urls = audioUrls();
331	  for (const def of AUDIO_DEFS) {
332	    const url = urls.get(def.key);
333	    if (url && !scene.cache.audio.exists(def.key)) scene.load.audio(def.key, url);
334	  }
335	}
336	
337	// ── Playback (mute is enforced globally by the shared sound manager) ──────────
338	export function playSfx(scene: Phaser.Scene, key: SfxKey): void {
339	  const volume = key === Sfx.ui ? AUDIO.uiVolume : AUDIO.sfxVolume;
340	  scene.sound.play(key, { volume });
341	}
342	
343	// Single looping music track shared across scenes (the sound manager is global).
344	let currentMusic: Phaser.Sound.BaseSound | undefined;
345	let currentMusicKey: MusicKey | undefined;
346	
347	export function playMusic(scene: Phaser.Scene, key: MusicKey): void {
348	  if (currentMusicKey === key && currentMusic && (currentMusic.isPlaying || currentMusic.isPaused)) {
349	    return; // already the active track — don't restart or stack
350	  }
351	  stopMusic();
352	  const music = scene.sound.add(key, { loop: true, volume: AUDIO.musicVolume });
353	  music.play();
354	  currentMusic = music;
355	  currentMusicKey = key;
356	}
357	
358	export function stopMusic(): void {
359	  if (currentMusic) {
360	    currentMusic.stop();
361	    currentMusic.destroy();
362	  }
363	  currentMusic = undefined;
364	  currentMusicKey = undefined;
365	}
366	
367	export function pauseMusic(): void {
368	  if (currentMusic && currentMusic.isPlaying) currentMusic.pause();
369	}
370	
371	export function resumeMusic(): void {
372	  if (currentMusic && currentMusic.isPaused) currentMusic.resume();
373	}
