1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import { ASSET_MANIFEST } from '../config/assetManifest';
4	import { t } from '../i18n/strings';
5	import { GAME_WIDTH, GAME_HEIGHT } from '../config/gameConfig';
6	import { registerAudio } from '../systems/audio';
7	
8	/**
9	 * PreloadScene — loads EVERY asset from the shared manifest (as SVGs at their
10	 * logical sizes) behind a loading bar, then advances to the menu. Nothing
11	 * critical is lazy-loaded (spec §10.5). (Audio unlock is installed once in
12	 * BootScene on a long-lived window listener, not here.)
13	 */
14	export class PreloadScene extends Phaser.Scene {
15	  constructor() {
16	    super({ key: SceneKey.Preload });
17	  }
18	
19	  preload(): void {
20	    this.buildLoadingBar();
21	
22	    // Fail LOUD if any manifest key is missing on disk (e.g. a new key added to
23	    // assetManifest.ts without regenerating placeholders → a silent 404). This
24	    // is a real error path, not log spam.
25	    this.load.on(Phaser.Loader.Events.FILE_LOAD_ERROR, (file: Phaser.Loader.File) => {
26	      console.error(`[assets] failed to load "${file.key}" from ${file.src} — is the SVG present?`);
27	    });
28	
29	    // The manifest is the single source of truth: iterate & load each SVG.
30	    for (const a of ASSET_MANIFEST) {
31	      this.load.svg(a.key, a.path, { width: a.width, height: a.height });
32	    }
33	
34	    // Placeholder SFX/music: synthesized to WAV blobs at runtime and queued onto
35	    // this same loader (no external files / network — 100% static-hostable).
36	    registerAudio(this);
37	  }
38	
39	  create(): void {
40	    this.scene.start(SceneKey.Menu);
41	  }
42	
43	  private buildLoadingBar(): void {
44	    const cx = GAME_WIDTH / 2;
45	    const cy = GAME_HEIGHT / 2;
46	    const barW = 520;
47	    const barH = 26;
48	
49	    this.add
50	      .text(cx, cy - 48, t('loading'), {
51	        fontFamily: 'system-ui, sans-serif',
52	        fontSize: '22px',
53	        color: '#f4f7fa',
54	      })
55	      .setOrigin(0.5);
56	
57	    const frame = this.add.graphics();
58	    frame.lineStyle(2, 0x5b6670, 1);
59	    frame.strokeRect(cx - barW / 2, cy - barH / 2, barW, barH);
60	
61	    const fill = this.add.graphics();
62	    const pct = this.add
63	      .text(cx, cy + 40, '0%', {
64	        fontFamily: 'system-ui, sans-serif',
65	        fontSize: '16px',
66	        color: '#9fb0bd',
67	      })
68	      .setOrigin(0.5);
69	
70	    this.load.on(Phaser.Loader.Events.PROGRESS, (value: number) => {
71	      fill.clear();
72	      fill.fillStyle(0x6cc04a, 1);
73	      fill.fillRect(cx - barW / 2 + 3, cy - barH / 2 + 3, (barW - 6) * value, barH - 6);
74	      pct.setText(`${Math.round(value * 100)}%`);
75	    });
76	  }
77	}
